  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// 1. Bảng Người dùng\nmodel User {\n  id                  String                      @id @default(uuid())\n  email               String                      @unique\n  password            String\n  fullName            String\n  role                String                      @default(\"USER\")\n  targetLevel         String?                     @default(\"B1\") // B1, B2, C1, C2 (Mức giao tiếp mục tiêu)\n  learningGoal        String?                     @default(\"PHONG_VAN\") // DU_HOC, PHAT_TRIEN, PHONG_VAN, GIAO_TIEP (Mục đích học)\n  createdAt           DateTime                    @default(now())\n  isVerified          Boolean                     @default(false)\n  verifyOtp           String? // Mã OTP 6 số\n  otpExpiresAt        DateTime?\n  histories           PracticeHistory[]\n  vocabularyPractices VocabularyPracticeHistory[]\n}\n\n// 2. Bảng Bài học / Đề tài Luyện nói\nmodel Lesson {\n  id          String   @id @default(uuid())\n  title       String\n  level       String   @default(\"B1\") // B1, B2, C1, C2\n  description String?\n  imageUrl    String? // Ảnh minh họa đề tài\n  createdAt   DateTime @default(now())\n\n  // Quan hệ 1 - N: Một bài học có nhiều câu thoại\n  dialogues DialogueLine[]\n}\n\n// 3. Bảng Câu thoại đối thoại\nmodel DialogueLine {\n  id            Int      @id @default(autoincrement())\n  lessonId      String\n  orderIndex    Int\n  speaker       String\n  characterName String\n  text          String\n  ipa           String?\n  translation   String?\n  createdAt     DateTime @default(now())\n\n  lesson    Lesson            @relation(fields: [lessonId], references: [id], onDelete: Cascade)\n  histories PracticeHistory[]\n\n  @@index([lessonId])\n}\n\n// 4. Bảng Lịch sử luyện nói\nmodel PracticeHistory {\n  id                  String       @id @default(uuid())\n  userId              String\n  dialogueLineId      Int\n  spokenText          String // Câu người dùng thực tế nói ra\n  accuracyScore       Int // Điểm % chính xác\n  feedback            String? // Nhận xét của AI\n  audioUrl            String? // File ghi âm (nếu muốn lưu lại để nghe lại)\n  createdAt           DateTime     @default(now())\n  mispronounced_words String\n  user                User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  dialogue            DialogueLine @relation(fields: [dialogueLineId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([dialogueLineId])\n}\n\n// 5. Bảng Chủ đề Từ vựng (VocabularyTopic)\nmodel VocabularyTopic {\n  id          String   @id @default(uuid())\n  name        String   @unique // Tên chủ đề (VD: Work & Study, AI & Technology...)\n  description String? // Mô tả chi tiết chủ đề từ vựng\n  imageUrl    String? // Đường dẫn ảnh đại diện của Chủ đề (URL hoặc Base64)\n  level       String   @default(\"B1\") // Trình độ: B1, B2, C1, C2\n  createdAt   DateTime @default(now())\n\n  // Quan hệ 1 - N: Một chủ đề có nhiều từ vựng và lịch sử làm bài (Chính tả / Trắc nghiệm)\n  vocabularies Vocabulary[]\n  practices    VocabularyPracticeHistory[]\n}\n\n// 6. Bảng Từ vựng (Vocabulary)\nmodel Vocabulary {\n  id           Int      @id @default(autoincrement())\n  topicId      String // Khóa ngoại liên kết tới Chủ đề Từ vựng\n  word         String // Từ vựng hoặc cụm từ tiếng Anh\n  pos          String   @default(\"Noun\") // Từ loại (Noun, Verb, Adjective, Phrasal Verb...)\n  ipa          String? // Phiên âm quốc tế IPA\n  meaning      String // Nghĩa tiếng Việt\n  level        String   @default(\"B1\") // Cấp độ: B1, B2, C1, C2\n  synonyms     String? // Từ đồng nghĩa nâng cấp\n  example      String? // Câu ví dụ tiếng Anh\n  exampleTrans String? // Bản dịch câu ví dụ tiếng Việt\n  createdAt    DateTime @default(now())\n\n  topic VocabularyTopic @relation(fields: [topicId], references: [id], onDelete: Cascade)\n\n  @@index([topicId])\n}\n\nmodel VocabularyPracticeHistory {\n  id             String   @id @default(uuid())\n  userId         String\n  topicId        String\n  practiceType   String   @default(\"DICTATION\") // \"DICTATION\" (Ghi chép chính tả) | \"QUIZ\" (Trắc nghiệm)\n  score          Int // Điểm phần trăm (0 - 100)\n  correctCount   Int      @default(0) // Số câu trả lời đúng\n  totalQuestions Int      @default(0) // Tổng số từ trong bài\n  detailsJson    String? // Chi tiết các từ đã viết đúng/sai (JSON)\n  createdAt      DateTime @default(now())\n\n  user  User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  topic VocabularyTopic @relation(fields: [topicId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([topicId])\n}\n",
